// Original RM extension. English explanations, French clarification, stable IDs.
const sec=(title,titleFr,text,help)=>({title,titleFr,text:text+' '+help,english:text,help});
export const extensionSpecs=[
{id:'adjectives-adverbs',name:'Adjectives and Adverbs: Meaning, Position and Traps',nameFr:'Adjectifs et adverbes : sens, place et pièges',group:0,goal:'Distinguish a quality from a manner, and check words whose -ly form changes meaning.',gap:'Word formation was covered, but adjective/adverb choice and position had no dedicated lesson.',sections:[
sec('1 · Describe a noun or describe an action?','Décrire un nom ou une action ?','An adjective gives a property of a noun: a careful driver, a useful explanation. An adverb can describe how an action happens: the driver checks carefully; the teacher explains clearly. Ask what the missing word modifies before looking at its ending. In The pupils gave a clear answer, clear describes answer, not gave. In The pupils answered clearly, clearly describes answered. At a debate in Buea, a confident speaker may speak confidently. Changing the sentence structure can change the required word class even when the basic idea stays the same.','Le mot voisin ne suffit pas : trouve ce qui est décrit. A clear answer = une réponse claire ; answer clearly = répondre clairement.'),
sec('2 · Linking verbs and the good/well contrast','Verbes attributifs et good/well','Be, seem, become, look, sound, smell, taste and feel can link the subject to a quality: the plan sounds sensible; the soup tastes good. These uses normally take adjectives, not adverbs of manner. Compare She looked carefully at the label: here looked describes a deliberate action. Good is usually an adjective, while well commonly describes performance: a good singer sings well. Well can also be an adjective meaning healthy: I do not feel well. Therefore a rule such as always add -ly after a verb gives wrong answers. Decide whether the word describes the subject or the performance.','The soup tastes good décrit la soupe ; she tastes the soup carefully décrit sa façon de goûter. Well peut aussi signifier en bonne santé.'),
sec('3 · Hard, hardly, late and lately','Les faux couples en -ly','Some adverbs have the same form as an adjective: a fast runner runs fast; a hard task requires people to work hard. Hardly usually means almost not, not with effort: I can hardly hear you means that hearing is difficult. Late means after the expected time, whereas lately refers to a recent period: the bus arrived late; I have been tired lately. Nearly means almost, while near concerns closeness. Do not build these contrasts by attaching -ly mechanically. In a listening task, missing hardly can reverse your understanding of what a speaker managed to do.','Work hard = travailler avec effort ; hardly work = ne presque pas travailler. Late = en retard ; lately = récemment. Apprends chaque contraste avec son contexte.'),
sec('4 · Adjectives ending in -ly and adjective order','Les adjectifs en -ly et leur ordre','Friendly, lovely and lonely are adjectives despite their ending. Write a friendly receptionist or she spoke in a friendly way; do not invent friendlily for ordinary school writing. Before a noun, several adjectives tend to follow a conventional order: opinion before size, age, colour, origin and material. A useful small wooden box is natural. This is a tendency serving clarity, not a reason to pile up six adjectives. Material words such as wooden stay unchanged before plural nouns: wooden chairs, not woodens chairs. When unsure, split a crowded noun phrase into a second sentence.','Un mot en -ly n’est pas forcément un adverbe. Les adjectifs ne prennent pas le pluriel du nom : useful books, et non usefuls books.'),
sec('5 · Position and the meaning of only','Place de l’adverbe et portée de only','An adverb of manner often follows the object: she explained the rule clearly. Do not normally separate a verb from a short object by inserting carefully: she checked the receipt carefully is the useful school model. Frequency adverbs often come before the main verb but after be: she usually checks; she is usually ready. Only needs special attention. Only Amina borrowed the book limits the borrower. Amina borrowed only the book limits what she borrowed. In speech stress can help, but in writing place only close to the intended focus to reduce ambiguity.','Only change ce que tu limites : la personne, l’objet ou une autre partie. Écris près du mot visé, puis vérifie que le sens n’a pas changé.'),
sec('6 · Proofread a description and an explanation','Relire une description et une explication','Use three checks in an exam transformation. First identify the word being described. Second decide whether the construction needs an adjective, an adverb or a phrase such as in a friendly way. Third check that the chosen form has the intended meaning. The instructions were clear, so we completed the task easily combines a quality with a manner. The instructions were hardly clear gives a different judgement. In your own paragraph, underline each modifier and explain its job. A precise short sentence is more effective than an unusual adverb chosen only to sound advanced.','Ne choisis pas un mot parce qu’il paraît compliqué. Contrôle sa fonction, sa forme et son sens, puis relis toute la phrase.')],rows:[
['Complete: The receptionist answered the question ___. (polite)','politely','polite','politeness','Answered décrit une action : politely en précise la manière. Polite qualifie un nom ; politeness est un nom.'],
['Complete: This meal tastes ___. (pleasant flavour)','good','wellly','goodly','Taste relie ici le repas à une qualité : good. Les deux autres propositions ne sont pas les formes attendues.'],
['Complete: The pupils worked ___ to finish on time. (with effort)','hard','hardly','hardness','Hard signifie avec effort ; hardly signifie presque pas et hardness est un nom.'],
['Complete: I have not seen her ___. (recently)','lately','late','lateness','Lately désigne la période récente ; late indique un retard et lateness est un nom.'],
['Choose the natural phrase describing a warm manner.','in a friendly way','in a friend way','in a friendliness','Friendly est adjectival ; in a friendly way exprime naturellement la manière. Friend est un nom et friendliness aurait besoin d’une autre construction.'],
['Which sentence clearly says that Amina, and nobody else, borrowed the book?','Only Amina borrowed the book.','Amina borrowed only the book.','Amina only borrowed the book.','Only placé devant Amina limite la personne ; les autres placements peuvent limiter l’objet ou l’action.'],
['Complete: We could ___ hear the announcement; the room was very noisy.','hardly','hard','hardness','Hardly indique presque pas ; le bruit gêne l’écoute. Hard exprime l’effort et hardness est nominal.'],
['Choose the standard word order.','She checked the form carefully.','She checked careful the form.','She carefully the form checked.','Le modèle neutre place l’objet après le verbe, puis la manière. Les autres ordres ne sont pas le choix standard demandé.']],production:['Describe a helpful classmate in four sentences. Use two adjectives, two adverbs and a contrast between hard and hardly.','Amina is patient and friendly. She explains difficult tasks clearly. She works hard when a deadline is close. In a noisy room, we can hardly hear her.','Distingue qualités et manière ; hard doit signifier avec effort, hardly presque pas.'],objectives:[['Describe a person and the way they perform two actions.','Décris une personne puis sa façon d’agir.','She is careful. She reads instructions carefully.','Relie chaque adjectif à un nom et chaque adverbe à une action.'],['Contrast two meanings of look or taste.','Oppose deux emplois de look ou taste.','The soup tastes good. She tastes it carefully.','Le premier complément qualifie le sujet ; le second décrit l’action.'],['Write a pair of sentences contrasting hard and hardly.','Oppose hard et hardly.','They work hard. They hardly complain.','Le sens de hardly est presque pas, jamais avec effort.'],['Move only and explain the change in meaning.','Déplace only et explique le sens.','Only Nelly read the report. Nelly read only the report.','Identifie précisément l’élément limité dans chaque phrase.'],['Revise a description containing a friendly person and a fast action.','Révise une description avec friendly et fast.','A friendly volunteer spoke in a friendly way, then ran fast to the gate.','N’invente pas un adverbe en -ly pour friendly ou fast.']]},
{id:'place-movement',name:'Prepositions of Place and Movement',nameFr:'Prépositions de lieu et de déplacement',group:0,goal:'Describe position, direction and a route without translating French prepositions word for word.',gap:'Time prepositions had a full chapter; spatial relationships and directions did not.',sections:[
sec('1 · Position: in, on and at','Position : in, on et at','In presents something inside a space or area: in the classroom, in Douala. On commonly describes contact with a surface: on the desk, on the wall. At treats a location as a point or activity location: at the gate, at school. These viewpoints can overlap: in the school describes being inside the building, while at school can refer to attending school. Choose the intended viewpoint instead of assuming one French word has one English equivalent. On a map, distinguish an address point from the inside of a building before selecting the preposition.','À ne se traduit pas toujours par at. At school et in the school peuvent viser le même endroit sous deux points de vue différents.'),
sec('2 · Direction: to, into and onto','Direction : to, into et onto','To gives a destination: walk to the library. Into emphasises crossing a boundary to the inside: walk into the library. Onto presents movement to a surface: put the parcel onto the shelf. Compare the ball is in the box with the ball rolls into the box. Position and movement are different relations. Not every moving verb requires to: go home, come here and walk there normally have no to because these expressions already function as destinations. In a route description, state where a traveller is going and whether entering the place matters.','In décrit une position ; into souligne une entrée. Go home se construit sans to : home fonctionne ici comme destination.'),
sec('3 · Across, through, along and past','Traverser, longer et dépasser','Across usually takes you from one side of an area to the other: walk across the road. Through presents movement within something that surrounds the route: walk through a tunnel or through the market. Along follows the length of a road or river. Past means beyond a reference point: go past the post office. At a junction in Bamenda, Walk along the road, past the pharmacy, then across the bridge describes three different relations. The French traverser is not enough to decide between across and through; imagine the shape of the space.','Across met en relation deux côtés ; through fait passer à l’intérieur. Along suit la longueur ; past dépasse un repère.'),
sec('4 · Between, among, opposite and next to','Entre, parmi et à côté','Between relates separate, identifiable people or things; it is not limited mechanically to two when several distinct parties are involved. Among places someone or something within a group: she stood among the spectators. The office between the bank and the shop gives two clear boundaries. Opposite means facing on the other side, while next to means immediately beside. Near is less precise and does not guarantee adjacency. When giving directions to a visitor, replace vague near references with a named landmark and a clear relation whenever possible.','Between ne signifie pas exclusivement entre deux dans tous les emplois. Pour un groupe envisagé collectivement, among est souvent approprié.'),
sec('5 · Above, over, below and under','Position verticale et nuances','Above and below describe higher or lower positions without requiring direct vertical alignment: a village above the lake. Over and under often suggest a position directly across or beneath something: a bridge over the river, a bag under the chair. Their meanings extend beyond literal space: over twenty pupils means more than twenty, and under supervision means supervised. Beside means next to, whereas besides can mean in addition to: beside the door is spatial; besides English, she studies history adds a subject. Read the full clause before assuming every preposition describes a physical location.','Beside = à côté ; besides = en plus de. Les mots spatiaux ont aussi des emplois abstraits : under supervision n’évoque pas une position sous un objet.'),
sec('6 · Give a route that another person can follow','Donner un itinéraire exploitable','Start from an agreed point, such as the school gate. Give one movement at a time and check left or right from the traveller’s viewpoint. Walk along the main road. Go past the shop. Turn left at the junction. The clinic is opposite the library. A reader should be able to sketch the route without guessing the starting direction. In a gap exercise, inspect the verb and its complement: arrive at a small destination, arrive in a city, but reach a place without at. Avoid arrive to in the ordinary arrival construction.','Relis l’itinéraire comme un visiteur. Arrive at the station, arrive in Yaoundé, reach the station : le verbe commande aussi la construction.')],rows:[
['Complete: The keys are ___ the closed drawer. (inside)','in','into','to','In exprime la position intérieure ; into exprimerait un déplacement et to une destination.'],
['Complete: The ball rolled ___ the box. (from outside to inside)','into','in front of','at','Into marque le franchissement de la limite vers l’intérieur ; les autres relations ne donnent pas ce trajet.'],
['Complete: Walk ___ the tunnel to reach the other entrance.','through','above','besides','Through décrit un passage à l’intérieur du tunnel ; above serait au-dessus et besides signifie en plus de.'],
['Complete: They arrived ___ Yaoundé before noon.','in','to','into','Arrive in s’emploie pour une ville ; arrive to n’est pas la construction standard et into n’est pas attendu ici.'],
['Choose the sentence that means the office is immediately beside the library.','The office is next to the library.','The office is beyond the town.','The office is far from the library.','Next to signifie juste à côté. Beyond the town et far from donnent d’autres positions.'],
['Complete: ___ English, she also studies history. (in addition to)','Besides','Beside','Between','Besides ajoute une matière ; beside donne une position et between appelle une relation entre éléments.'],
['Choose the standard expression.','We went home after school.','We went to home after school.','We went at home after school.','Avec go, home fonctionne comme destination sans préposition dans cet emploi.'],
['Complete: Go ___ the shop; the entrance is a little farther along the road.','past','into','under','Past signifie dépasser le magasin pour continuer ; into ferait entrer et under passer dessous.']],production:['Give a four-step route from a school gate to a library. Include along, past, across and one final position.','Walk along the main road. Go past the market. Walk across the bridge. The library is next to the clinic.','L’ordre doit permettre de suivre un trajet ; distingue mouvement et position finale.'],objectives:[['Describe three positions using in, on and at.','Décris trois positions avec in, on et at.','The book is in the bag, the bag is on the desk, and I am at the door.','Chaque préposition doit correspondre à la relation décrite.'],['Contrast a position with movement into a place.','Oppose une position à une entrée.','The pupils are in the hall. A visitor walks into the hall.','Le passage de la limite doit être explicite dans la seconde phrase.'],['Write a route using along, past and across.','Écris un trajet avec along, past et across.','Walk along the road, past the bank, then across the square.','Choisis des repères distincts et un ordre cohérent.'],['Compare beside and besides in two sentences.','Distingue beside et besides.','The shop is beside the school. Besides books, it sells pens.','Ne confonds pas position et ajout.'],['Correct a route with an unclear starting point.','Corrige un itinéraire sans point de départ clair.','From the school gate, turn right and walk to the clinic.','Précise le point de départ et le point de vue du voyageur.']]},
{id:'causatives',name:'Causatives: Have and Get Something Done',nameFr:'Faire faire : constructions causatives',group:0,goal:'Explain who arranges an action, who performs it and what receives it. Optional extension beyond the core revision list.',gap:'Passive voice and make were mentioned, but arranged services and their contrast with the Perfect were not developed.',sections:[
sec('1 · Arrange an action instead of performing it','Organiser une action plutôt que la faire soi-même','I repaired the bicycle says that I did the repair. I had the bicycle repaired normally says that I arranged for another person to repair it. The service may be paid or unpaid; payment is not part of the grammar. The pattern is have + object + past participle. In She has her uniform altered, her uniform receives the alteration. A causative sentence draws attention to the arrangement and result, so the performer can remain unnamed. This extension is useful for describing repairs and services, but it is not presented as a separately verified compulsory Bac chapter.','Faire réparer n’est pas réparer soi-même. Identifie l’organisateur, l’objet et la personne qui agit, même si cette dernière n’est pas nommée.'),
sec('2 · Put the tense on have or get','Porter le temps sur have ou get','Change have to locate the arrangement in time: she has her hair cut regularly; she had it cut yesterday; she will have it cut tomorrow. The final participle stays cut. Get can often replace have in a less formal service description: we got the printer repaired. Negatives and questions usually use do with causative have in simple tenses: Did you have the screen replaced? We did not have it replaced. Do not write Did you had: did already carries the past. Continuous arrangements are also possible: we are having the classroom painted this week.','Le temps varie sur have/get ; le participe final garde sa forme. Did you have, et non did you had. Le contexte décide si le service est habituel, passé ou en cours.'),
sec('3 · Do not confuse causative have with the Perfect','Ne pas confondre causatif et Perfect','Compare I have repaired the bike with I have the bike repaired every year. In the first, have is the Perfect auxiliary followed directly by the participle; I normally performed the repair. In the second, the bike stands between have and repaired and receives an arranged service. A Perfect causative combines both: I have had the bike repaired. The first have is the auxiliary, had is the participle of causative have, and repaired describes the action affecting the bike. Identify each job rather than counting how many forms of have appear.','I have repaired = j’ai réparé. I have had it repaired = je l’ai fait réparer. L’ordre des mots donne la différence de rôle.'),
sec('4 · Name the person: have someone do, get someone to do','Nommer la personne qui agit','When the performer is stated as the object, use have + person + base verb: the organiser had a volunteer check the list. With get, the standard pattern includes to: she got a volunteer to check the list. Compare that with she had the list checked, where the list receives the action. Do not swap the objects without changing the verb form. In a transformation, underline whether the object is a person doing something or a thing receiving something. The distinction matters more than choosing between the near-synonyms have and get.','Have someone do utilise la base ; get someone to do utilise to. Have something done utilise un participe parce que l’objet subit l’action.'),
sec('5 · Make, let and allow are not interchangeable','Make, let et allow expriment des relations différentes','Make someone do can describe causing or requiring an action: the noise made us stop. Let someone do gives permission: the teacher let us leave. Allow someone to do also gives permission but takes to. In the passive, make regains to: we were made to wait. The normal passive counterpart of let in this sense is be allowed to: we were allowed to leave. These structures overlap with the earlier verb-pattern course; here they help explain who controls an action. Do not turn a permission into an obligation merely to keep the same verb form.','La forme ne suffit pas : make peut imposer, let et allow permettent. Au passif : made to wait, allowed to leave.'),
sec('6 · An unwanted event and a careful exam rewrite','Événement subi et transformation fidèle','Have + object + participle can also describe an unwanted experience: she had her bag stolen. This does not mean that she commissioned the theft. Context determines whether the subject arranged or suffered the event. For an ordinary service transformation, keep the time and result: A technician checked our printer yesterday becomes We had our printer checked yesterday. Do not invent a payment, a guarantee or a completed repair if the original only says checked. In speaking, naming the performer may be clearer when responsibility matters.','She had her bag stolen = elle s’est fait voler son sac, pas elle a commandé le vol. Une transformation doit conserver les faits et le temps.')],rows:[
['Complete: We had the classroom ___ by a decorator. (paint)','painted','paint','painting','Have + objet recevant l’action + participe : painted. La base et -ing ne conviennent pas au service terminé décrit.'],
['Complete: The organiser got a volunteer ___ the list.','to check','checked','check','Get + personne + to-infinitif. Checked conviendrait avec la liste comme objet ; check sans to suit have dans cette construction.'],
['Complete: The teacher let us ___ early.','leave','to leave','left','Let + personne + base ; ni to ni prétérit après let dans ce modèle.'],
['Complete: Did you ___ your screen replaced yesterday?','have','had','having','Did porte le passé ; causative have reste à la base.'],
['Which sentence normally means I arranged for someone else to repair the bike?','I had the bike repaired.','I repaired the bike myself.','I have repaired the bike myself.','L’objet entre had et repaired reçoit le service organisé. Myself dans les autres phrases précise que le sujet a agi.'],
['Complete: We were made ___ outside.','to wait','wait','waiting','Au passif de make someone do, la construction est be made to do.'],
['She had her bag stolen. What does this normally describe?','An unwanted experience','A service she deliberately ordered','Proof that she stole a bag','Have something done peut décrire un événement subi ; le contexte de vol ne présuppose pas un service commandé.'],
['Complete: I have ___ the printer repaired. (a service arranged, now completed)','had','have','having','Le Perfect causatif utilise have + had + objet + participe. Le second have doit être au participe had.']],production:['Describe an arranged service, name its performer in a second sentence, and contrast it with a task you did yourself.','I had my bicycle repaired yesterday. I got a mechanic to replace the chain. I cleaned the bicycle myself afterwards.','Vérifie objet + participe, personne + to après get et action personnelle distincte.'],objectives:[['Contrast doing a repair yourself with arranging it.','Oppose réparer et faire réparer.','I repaired the chair. I had the chair repaired.','La seconde phrase change la responsabilité de l’action.'],['Describe the same service in the past and future.','Décris un service au passé puis au futur.','We had the roof checked. We will have it checked again.','Le participe checked reste identique ; le temps porte sur have.'],['Name a performer using have and then get.','Nomme un exécutant avec have puis get.','I had a friend check it. I got a friend to check it.','Base après have someone ; to après get someone.'],['Distinguish permission from obligation.','Distingue permission et obligation.','We were allowed to leave, but we were made to sign first.','Explique qui permet et qui impose sans confondre le sens.'],['Explain an unwanted have-something-done event.','Explique un événement subi avec have.','She had her phone stolen; she did not ask for that to happen.','Ne présente pas l’événement subi comme un service volontaire.']]},
{id:'agreement-replies',name:'Agreeing and Disagreeing: So, Neither, Too and Either',nameFr:'Répondre : moi aussi, moi non plus et désaccord',group:0,goal:'Build short replies that match the auxiliary, polarity and meaning of the first statement.',gap:'Question tags were taught, but replies expressing shared situations had no systematic practice.',sections:[
sec('1 · Share a positive situation','Partager une situation affirmative','I enjoy reading. — So do I. The reply says that the second speaker also enjoys reading. The pattern is so + auxiliary + subject. If the first statement already has an auxiliary or a form of be, reuse it with the new subject: I am ready. — So are we. She can swim. — So can I. If an ordinary Present Simple verb has no auxiliary, use do or does. The reply is not a question, even though its word order resembles one. In a school conversation, make sure the shared meaning is true for the second speaker before choosing an automatic agreement formula.','Moi aussi ne devient pas toujours so do I : choisis l’auxiliaire de la première phrase et adapte-le au nouveau sujet.'),
sec('2 · Share a negative situation','Partager une situation négative','I cannot attend. — Neither can I. Neither already gives the negative meaning, so do not add not to the auxiliary. I have not finished. — Neither have we. Nor can often serve a similar function, particularly when linking clauses. The common informal reply Me neither communicates agreement, but a school transformation asking for an auxiliary expects the full pattern. Remember that hardly and never can give a clause a negative meaning even without not. Use the meaning of the original statement, not just a search for the letters not.','Neither can I = moi non plus. Neither can’t I cumule incorrectement deux marques négatives dans la construction demandée.'),
sec('3 · Keep normal order with too and not…either','Garder l’ordre habituel avec too et either','Positive agreement can also use a full clause with too: I enjoy reading too. A shorter reply is I do too. Negative agreement uses not…either: I do not enjoy it either, or I do not either when the omitted action is clear. These clauses keep subject before auxiliary. Compare Neither do I with I do not either: both can express the same shared negative situation, but their structures are different. Either in this construction does not mean a choice between two items. Avoid I do not too when you mean moi non plus.','Deux modèles à distinguer : Neither + auxiliaire + sujet ; sujet + auxiliaire négatif + either. Ne mélange pas les deux ordres.'),
sec('4 · Track tense and the new subject','Suivre le temps et le nouveau sujet','We visited the museum. — So did they. I have seen the film. — So has Amina. The reply keeps the tense or auxiliary family of the first clause, but agreement belongs to the new subject. The same rule applies to be: I was late. — So were we. A common error is copying have after a new singular subject or using do for every tense. In a transformation, write the full repeated statement first, then shorten it. Amina has seen the film shows why the short reply must be So has Amina.','Le temps vient du premier énoncé ; l’accord dépend du nouveau sujet. La phrase développée permet de contrôler la réponse courte.'),
sec('5 · Disagreement and confirming the same person','Désaccord et confirmation du même sujet','I am not tired. — I am expresses a different situation, not shared agreement. I enjoyed the lecture. — I did not disagrees. Keep the response polite by adding a reason rather than attacking the speaker. There is another useful contrast: So do I means I do that too, whereas So I do can acknowledge a fact about the same speaker, as when someone notices a mistake and accepts the observation. These are not interchangeable word orders. In an exam, identify whether the task asks for agreement, disagreement or confirmation before selecting a pattern.','So do I ajoute une autre personne à la situation. So I do confirme quelque chose au sujet de I ; ce n’est pas la même réponse.'),
sec('6 · Build a natural exchange','Construire un échange naturel','Use four decisions: identify positive or negative meaning; find the auxiliary or supply do; locate the new subject; decide whether the reply agrees. At a club meeting: I have not printed the notices. — Neither have I, but Nelly has. This exchange shares a negative situation, then contrasts a third person. Do not infer that everyone failed to print them. In writing, short replies should have an obvious previous clause; otherwise the reader may not know what has been omitted. This lesson extends the work on auxiliaries and question tags without replacing it.','Un auxiliaire isolé reprend une action déjà connue. Sans phrase précédente claire, développe la réponse pour éviter l’ambiguïté.')],rows:[
['Complete the agreeing reply: I enjoy debates. — So ___ I.','do','am','have','Enjoy est au Present Simple sans auxiliaire ; do reprend cette action, pas am ni have.'],
['Complete the agreeing reply: I am ready. — So ___ we.','are','do','am','La première phrase utilise be ; le nouveau sujet we demande are.'],
['Complete the agreeing reply: I have not finished. — Neither ___ she.','has','does','has not','Le Perfect appelle has avec she ; neither porte déjà la négation.'],
['Complete: I cannot attend, and I cannot drive there ___.','either','too','neither','Après une proposition déjà négative, either signifie non plus. Neither demanderait une autre construction.'],
['Complete the agreeing reply: We visited Buea. — So ___ they.','did','have','do','Visited est au prétérit ; did reprend le passé, sans transformer en bilan présent.'],
['Which reply expresses disagreement with “I am not tired”?','I am.','Neither am I.','I am not either.','I am affirme être fatigué et contredit la situation du premier locuteur. Les autres réponses partagent sa négation.'],
['Choose the standard negative agreement.','Neither can I.','Neither cannot I.','Neither I can.','Neither + auxiliaire affirmatif + sujet est la structure attendue ; pas de négation ajoutée ni d’ordre sujet-verbe ici.'],
['Complete the agreeing reply: I have read it. — So ___ Amina.','has','have','does','Has conserve le Perfect et s’accorde avec Amina. Have ne convient pas à ce sujet singulier.']],production:['Write a four-line exchange containing positive agreement, negative agreement and a respectful disagreement.','I enjoy group work. — So do I. I cannot stay late. — Neither can I. I think this plan is impossible. — I do not; we could divide the tasks.','Choisis l’auxiliaire correspondant à chaque énoncé ; distingue accord et désaccord.'],objectives:[['Agree with three positive statements using different auxiliaries.','Réponds à trois affirmations avec des auxiliaires différents.','I am ready. So am I. I can help. So can she.','N’utilise pas do quand be ou un modal est déjà présent.'],['Agree with two negative statements.','Partage deux situations négatives.','I have not called. Neither have we.','Neither porte la négation ; conserve le temps.'],['Rewrite a neither reply using not…either.','Reformule neither avec not…either.','Neither do I. I do not either.','Inverse l’ordre selon le modèle choisi, sans changer le sens.'],['Change the subject in a Perfect agreement reply.','Change le sujet dans une réponse au Perfect.','So have we becomes So has Nelly.','Vérifie l’accord avec le nouveau sujet.'],['Write a disagreement and give a respectful reason.','Exprime un désaccord avec une raison respectueuse.','I do not agree; the timetable leaves no time for lunch.','La réponse doit réellement différer de l’énoncé initial.']]},
{id:'emphasis-inversion',name:'Emphasis and Inversion: Not Only, Never and Only After',nameFr:'Emphase et inversion : approfondissement',group:0,goal:'Recognise formal emphasis and transform word order without confusing it with a question. Optional advanced extension.',gap:'Indirect questions avoided inversion, but fronted negative adverbials and cleft emphasis were not explained.',sections:[
sec('1 · Keep ordinary order until a reason changes it','Partir de l’ordre ordinaire','The ordinary statement is She had never seen such a crowd: subject, auxiliary, adverb and main verb. A formal emphatic version is Never had she seen such a crowd. Moving a negative or limiting adverbial to the front can trigger auxiliary-subject inversion. The sentence remains a statement. This advanced extension helps you recognise formal writing and controlled transformations; ordinary clear sentences remain appropriate in most compositions. It is not a requirement to add inversion to sound educated, and no frequency at the Cameroonian Bac is claimed here.','L’inversion n’en fait pas une question. On choisit cette structure pour une emphase formelle ; une phrase ordinaire correcte reste préférable à une inversion mal maîtrisée.'),
sec('2 · Find the auxiliary, or supply do','Trouver l’auxiliaire ou ajouter do','With an existing auxiliary, move it before the subject: she has never complained becomes Never has she complained. With a modal, use the same process: Never would I accept that condition. If an ordinary Present or Past Simple verb has no auxiliary, supply do, does or did and return the main verb to its base: Rarely does he miss a lesson; Never did they blame the volunteers. Do not write Never did they blamed. Be can invert directly: Never was the room completely empty. The time and the original meaning must remain unchanged.','Après did ou does, le verbe lexical revient à la base. Vérifie temps, accord et forme finale séparément.'),
sec('3 · Not only and parallel additions','Not only et ajout parallèle','Not only did she organise the event, but she also wrote the report adds a second achievement. Inversion belongs to the first clause because not only introduces it. The second clause keeps ordinary statement order. However, Not only Amina but also Nelly attended has a coordinated subject, not a fronted negative adverbial modifying the clause; it does not need did attend. First identify what not only introduces. A balanced structure compares actions with actions or people with people, instead of joining fragments with incompatible grammatical functions.','Not only Amina but also Nelly est un sujet composé : pas d’inversion automatique. L’analyse de la fonction évite d’appliquer une formule à tort.'),
sec('4 · Only after, only when and not until','Only after, only when et not until','Only after the meeting did we understand the problem places the limiting phrase first, then inverts the main clause. If the opening contains its own subject and verb, keep them in ordinary order: Only when the meeting ended did we leave. Do not invert the when clause. Not until the next day did she receive an answer similarly emphasises the delayed event. Only Amina understood is different: only limits the subject Amina, so the main statement keeps normal order. Ask which part of the sentence the limiting word modifies before moving an auxiliary.','Dans Only when…, l’inversion vient dans la principale, pas après when. Only devant le sujet seul ne déclenche pas ce mécanisme.'),
sec('5 · Hardly…when and no sooner…than','Hardly…when et no sooner…than','Hardly had we sat down when the bell rang expresses two events following one another very closely. No sooner had we sat down than the bell rang gives a similar sequence. Learn the pairings when and than rather than swapping them. The earlier event commonly uses the Past Perfect; the following event uses the Past Simple. These expressions are formal narrative tools, not statements that the first event never happened. Distinguish them from hardly meaning almost not in a clause such as I could hardly hear the bell. The surrounding construction determines the interpretation.','Hardly…when et no sooner…than racontent une succession immédiate. Ne transforme pas cette proximité en absence complète du premier événement.'),
sec('6 · Cleft sentences and restrained editing','Phrases clivées et relecture','It was Amina who found the missing page highlights the person. It was the missing page that Amina found highlights the object. These cleft sentences give emphasis without negative inversion. What we need is a clear timetable focuses attention on a need. In a rewrite, preserve who did what: highlighting a different phrase must not invent a different event. Use one marked structure when it serves the message, then return to ordinary sentences. To check an inverted sentence, restore normal order and compare it with the original; any changed tense or actor reveals a mistake.','L’emphase modifie la mise en relief, pas les faits. Reviens à l’ordre normal pour contrôler qui agit, à quel moment et sur quoi.')],rows:[
['Complete: Never ___ she complained about the timetable. (Present Perfect)','has','does','did','Le Perfect exige has + participe ; l’auxiliaire précède she après never en tête.'],
['Complete: Rarely does he ___ a lesson. (miss)','miss','misses','missed','Does porte l’accord et impose la base miss, pas misses ni missed.'],
['Complete: Only when the meeting ended ___ we leave. (past)','did','do','had','La principale au prétérit utilise did + leave ; l’inversion ne se place pas dans la subordonnée when.'],
['Complete: No sooner had we arrived ___ the rain started.','than','when','that','La paire standard est no sooner…than ; hardly s’associe normalement à when dans cette construction.'],
['Choose the standard sentence with a limited subject.','Only Amina knew the code.','Only did Amina knew the code.','Only Amina did knew the code.','Only limite ici le sujet ; aucune inversion n’est nécessaire. Les autres formes doublent aussi mal le passé.'],
['Complete: Not only did she organise the event, but she also ___ the report. (write, past)','wrote','write','writing','La seconde proposition garde l’ordre ordinaire et son prétérit wrote. Elle ne partage pas le did de la première.'],
['Complete: Hardly had we sat down ___ the lights went out.','when','than','because of','Hardly…when est la paire attendue ; because of demanderait un groupe nominal.'],
['Which sentence highlights who found the page?','It was Nelly who found the page.','It was the page that Nelly found.','Nelly found only the page.','La première met la personne en relief ; les autres focalisent l’objet ou sa limitation.']],production:['Rewrite “She had never seen such a crowd” with Never first. Then write one cleft sentence identifying who organised the event.','Never had she seen such a crowd. It was Amina who organised the event.','Préserve le Past Perfect et place had avant she ; la phrase clivée doit identifier clairement la personne.'],objectives:[['Move never to the front of a Perfect statement.','Place never en tête d’une phrase au Perfect.','Never have we received so many requests.','Déplace l’auxiliaire, sans perdre le participe.'],['Use rarely with an ordinary Present Simple verb.','Emploie rarely avec un Present Simple.','Rarely does the club cancel a meeting.','Ajoute does et garde le verbe à la base.'],['Contrast only plus a subject with only after plus an event.','Oppose only devant le sujet et only after.','Only Nelly replied. Only after lunch did Nelly reply.','Explique pourquoi seule la seconde structure inverse l’auxiliaire.'],['Narrate two close events using no sooner…than.','Raconte deux événements avec no sooner…than.','No sooner had we opened the gate than the visitors arrived.','Garde la paire than et une chronologie cohérente.'],['Highlight a person and then an object in cleft sentences.','Mets en relief une personne puis un objet.','It was Amina who found it. It was the key that she found.','Les faits doivent rester identiques quand la focalisation change.']]},
{id:'noun-phrases',name:'Possessive Nouns and Compound Noun Phrases',nameFr:'Génitif, noms composés et groupes nominaux',group:0,goal:'Read and write ownership, compound nouns and numerical modifiers with accurate plurals and apostrophes.',gap:'Possessive pronouns were covered; noun genitives, compound plurals and numerical modifiers were not.',sections:[
sec('1 · Possession is more than a possessive pronoun','Exprimer le possesseur avec un nom','Her bag uses a possessive determiner. Amina’s bag uses a noun in the possessive, traditionally called the genitive. For a singular possessor, add apostrophe plus s: the teacher’s desk. The possessive can express relationships rather than legal ownership: the pupil’s answer, yesterday’s meeting. Do not confuse the possessive with a plural: teachers means more than one teacher, while teacher’s marks a relation to one teacher. Ask who or what is the possessor before placing the apostrophe. The number of objects owned does not determine where that mark goes.','The teacher’s books peut désigner plusieurs livres d’un seul professeur. L’apostrophe suit la forme du possesseur, pas celle des objets.'),
sec('2 · Regular and irregular plural possessors','Possesseurs pluriels réguliers et irréguliers','For a regular plural already ending in s, place the apostrophe after s: the teachers’ room, the pupils’ bags. For an irregular plural without final s, add apostrophe plus s: the children’s books, the women’s team. Do not write childrens because children is already plural. A name ending in s can follow different style conventions; James’s book is a common standard form. A fair exercise should avoid claiming that every alternative style is impossible. Compare the girl’s bicycle and the girls’ bicycles: one letter position changes how the owner group is understood.','Children est déjà pluriel : children’s, pas childrens’. Pour un pluriel régulier : pupils’, puisque le s est déjà présent.'),
sec('3 · Shared possession and separate possession','Possession commune et possession séparée','Amina and Nelly’s project normally presents one joint project. Amina’s and Nelly’s projects presents separate projects. Context still matters, so specify shared or separate when the distinction is important. Of is another way to express a relationship: the roof of the school, the end of the lesson. Avoid treating every French de as an instruction to use an apostrophe. A friend of mine is also standard; a friend of me is not the usual possessive expression. Choose a construction that makes the relationship easy to understand rather than forcing one pattern everywhere.','Un projet commun et deux projets séparés ne s’écrivent pas nécessairement de la même façon. Of reste naturel pour de nombreuses relations entre choses.'),
sec('4 · A noun can classify another noun','Un nom peut préciser un autre nom','A school library is a kind of library, not normally a statement that one school legally owns it. In a noun-noun compound, the first noun often stays singular: a book shop, a shoe shop, bus tickets. The last noun usually carries the main meaning and the plural: two school libraries. English has established exceptions such as sports centre and clothes shop, so use a dictionary rather than deleting every s. Some compounds are written as one word, some with a hyphen and some separately. Spelling conventions belong to the lexical item, not a universal join-everything rule.','Le dernier nom est souvent le noyau : library dans school library. Le premier nom classe ou précise ; il ne prend pas automatiquement le pluriel français.'),
sec('5 · Compound plurals and numerical modifiers','Pluriels composés et mesures avant le nom','The plural of mother-in-law is mothers-in-law because mother is the main noun. Ordinary compounds such as classroom take the plural at the end: classrooms. A number before a unit in an adjective-like modifier usually keeps the unit singular and uses hyphens: a two-hour lesson, a ten-year-old pupil. Compare The lesson lasts two hours and It is a two-hour lesson. The first states a duration using a plural noun; the second modifies lesson. Do not write a two-hours lesson. The number and unit behave differently depending on their grammatical job.','Two hours est une durée ; two-hour est un modificateur placé avant un nom. Repère la fonction avant de décider du s.'),
sec('6 · Read long noun phrases from the main noun','Lire le groupe à partir du nom principal','In a small school library renovation project, project is the main noun. The earlier words specify what kind of project it is. If a phrase becomes difficult to decode, expand it: a project to renovate a small school library. In proofreading, locate the main noun, identify any possessor, then check plural and apostrophe placement separately. The pupils’ two-hour workshop contains a plural possessor and a singular unit modifier for different reasons. A useful exam explanation names those functions instead of saying that English never uses s before another noun.','Déplie un groupe trop long. Un possessif, un pluriel et une mesure peuvent se côtoyer sans obéir à la même règle.')],rows:[
['Choose the phrase meaning the desk of one teacher.','the teacher’s desk','the teachers desk','the teachers’ desks','Teacher’s marque un seul possesseur. Teachers’ desks exprime plusieurs enseignants et bureaux ; teachers desk omet le possessif attendu.'],
['Choose the possessive form for books belonging to children.','children’s books','childrens’ books','childrens books','Children est un pluriel irrégulier sans s final ; on ajoute ’s. Childrens n’est pas ce pluriel standard.'],
['Complete: It is a ___ lesson. (lasting two hours)','two-hour','two-hours','two hours of','Avant lesson, le modificateur numérique utilise l’unité au singulier et des traits d’union : two-hour.'],
['Give the plural of mother-in-law.','mothers-in-law','mother-in-laws','mothers-in-laws','Mother est le nom principal à mettre au pluriel dans ce composé.'],
['Which phrase most clearly describes one joint project?','Amina and Nelly’s project','Amina’s and Nelly’s projects','Amina’s projects and Nelly’s projects','Le possessif à la fin du groupe avec project singulier présente un projet commun ; les autres formes décrivent des projets distincts.'],
['Choose the usual plural.','two school libraries','two schools library','two school library','Library est le noyau et devient libraries ; school précise le type de bibliothèque.'],
['Complete: She is a friend of ___. (belonging to my circle of friends)','mine','me','my','A friend of mine est le modèle possessif ; my doit accompagner un nom et me ne remplit pas cette fonction ici.'],
['Choose the standard sentence describing duration.','The workshop lasts three hours.','The workshop lasts three-hour.','The workshop lasts three-hours long.','Après lasts, three hours est un groupe de durée au pluriel, pas un modificateur pré-nominal.']],production:['Describe a joint school project, an item belonging to several pupils and the duration of its meeting. Use one possessive noun and one compound modifier.','Amina and Nelly’s project uses the pupils’ notes. They organise a two-hour meeting. The meeting lasts two hours.','Distingue possesseur commun, possesseur pluriel et unité singulière dans two-hour.'],objectives:[['Contrast one owner and several owners.','Oppose un possesseur et plusieurs.','The pupil’s bag is blue. The pupils’ bags are blue.','La place de l’apostrophe doit correspondre au nombre de possesseurs.'],['Use an irregular plural possessor.','Emploie un possesseur au pluriel irrégulier.','The children’s drawings are displayed.','Children est déjà pluriel ; ajoute ’s.'],['Describe a shared project and separate projects.','Distingue projet commun et projets séparés.','Nelly and Amina’s plan is ready. Nelly’s and Amina’s plans differ.','Le nombre de projets et les marques possessives doivent rester cohérents.'],['Convert a duration into a noun modifier.','Transforme une durée en modificateur.','The trip lasts two days. It is a two-day trip.','L’unité perd le pluriel dans le modificateur pré-nominal.'],['Expand a crowded noun compound into a clear phrase.','Déplie un groupe nominal chargé.','A school library repair plan becomes a plan to repair the school library.','Garde le même noyau et la même relation entre les éléments.']]},
{id:'verb-confusions',name:'Confusing Verbs: Say, Tell, Hear, Listen, Bring and Take',nameFr:'Verbes proches : sens et construction',group:1,goal:'Choose a verb by meaning, viewpoint and complement.',gap:'False friends existed; these everyday verb families lacked systematic comparison.',sections:[
sec('1 · Say and tell','Dire et raconter','Say introduces words or a message: She said that the office was closed. To name the listener, use say to: She said hello to me. Tell normally takes the listener directly: She told me that the office was closed. Do not write She said me. Tell also occurs in established expressions without a listener: tell a story, tell the truth, tell a lie. Therefore, the rule tell always requires a person is too broad. Identify both the message and its recipient before choosing the construction.','Repère le destinataire : told me, mais said to me. Tell the truth est une expression à apprendre comme un tout.'),
sec('2 · Speak, talk and discuss','Parler et discuter','Speak English describes using a language. Talk to a friend and speak to a friend are both possible; their difference is not an absolute formal/informal rule. Talk about the timetable introduces a topic with about. Discuss the timetable takes the topic directly, without about. Discuss the timetable with the teacher adds the other participant. When proofreading, separate three questions: what language is used, what topic is discussed and who participates? A correct French translation does not guarantee the English complement is correct.','On dit discuss a problem, mais talk about a problem. La préposition dépend du verbe, pas seulement du sens français.'),
sec('3 · Perception and attention','Perception et attention','Hear describes receiving sound; listen describes directing attention towards it. We listened carefully but could not hear the last word is coherent. Listen to the announcement needs to before its object. See can describe visual perception; look at directs attention; watch often involves observing an unfolding activity. Watch the match is natural, but see a film is also possible. Avoid an absolute rule that every moving object requires watch. Meaning, intention and established usage work together.','Listen to et look at demandent leur préposition. Hear et see prennent normalement directement l’objet dans ces sens.'),
sec('4 · Bring, take and fetch','Le point de vue du déplacement','A teacher waiting in the classroom can say Bring your notebooks here. A parent at home can say Take your notebooks to school. The same journey is described from different viewpoints. Bring often directs movement towards the speaker or the relevant meeting place; take often directs it away towards another destination. Fetch means go and get something, usually returning with it. A speaker can adopt the listener’s viewpoint, so here and there are useful clues rather than mechanical guarantees.','Détermine où se trouve le point d’arrivée pertinent. Fetch implique aller chercher ; bring et take dépendent du point de vue.'),
sec('5 · Teaching, learning and remembering','Apprendre et se souvenir','The teacher teaches English; the pupils learn English. French apprendre can describe either role, but English distinguishes them. Remind someone to do something causes that person to remember: Remind me to bring my receipt. Remember to bring your receipt describes the person’s own memory. This photograph reminds me of our trip introduces an association with of. Notice the person after remind and the different complements to do and of a noun. Write complete patterns, not isolated translated verbs.','Qui transmet ? Qui apprend ? Qui aide l’autre à se souvenir ? Ces rôles déterminent teach, learn, remind et remember.'),
sec('6 · A practical correction method','Méthode de correction','Read the whole sentence before replacing a verb. Underline its subject, circle any listener or learner, and identify the object. Then check the required preposition. In a school interview, I told the visitor about our club and I spoke English to the visitor describe different information. Both may be true. When two answers are grammatical, use the intended message to choose; when an exercise lacks enough context, explain the ambiguity instead of inventing a rigid rule.','Un bon choix conserve le message ET la construction. Compare une paire de phrases complètes avant de mémoriser la règle.')],rows:[
['She ___ me that the office was closed.','told','said','spoke','Tell prend directement le destinataire : told me. Say demanderait to me ; spoke ne convient pas à cette construction.'],
['Please listen ___ the final instruction.','to','at','of','Listen est suivi de to devant ce qu’on écoute ; les deux autres prépositions ne forment pas cette construction.'],
['Our teacher ___ us English.','teaches','learns','studies','Teach décrit la transmission au groupe us ; learn et study décrivent l’activité de celui qui apprend.'],
['Please ___ me to bring my receipt.','remind','remember','recall to','Remind someone to do something signifie aider cette personne à penser à une action. Remember ne prend pas ce modèle.'],
['Choose the standard sentence about discussing a timetable.','We discussed the timetable.','We discussed about the timetable.','We discussed to the timetable.','Discuss prend le sujet discuté directement, contrairement à talk about.'],
['The teacher is waiting in the classroom: Please ___ your notebooks here.','bring','take away','leave behind','Bring indique ici un déplacement vers le lieu où attend la personne qui parle.'],
['We listened carefully but could not ___ the last word.','hear','listen','look at','Hear décrit le résultat perceptif ; listen seul ne prend pas directement the last word.'],
['The photograph reminds me ___ our trip.','of','to','with','Remind someone of something évoque un souvenir ; remind someone to do something introduirait une action.']],production:['Describe helping a younger pupil. Use teach, learn, listen to and remind someone to.','I taught my cousin a method. She learnt to plan. I listened to her questions and reminded her to check her work.','Vérifie les rôles enseignant/apprenant, listen to et remind + personne + to + verbe.'],objectives:[['Report one message with say and tell.','Rapporte un message avec say et tell.','She said that it was ready. She told me that it was ready.','Tell prend ici le destinataire directement.'],['Contrast listening effort and hearing a result.','Oppose effort d’écoute et résultat.','I listened but could not hear the answer.','L’attention ne garantit pas la perception.'],['Describe one journey from two viewpoints using bring and take.','Change le point de vue du déplacement.','Bring it here. Take it to the school.','Indique clairement les lieux et les points de vue.'],['Describe the teacher and learner roles.','Distingue celui qui enseigne et celui qui apprend.','I taught her a rule. She learnt it.','Teach transmet ; learn acquiert.'],['Write a reminder and a personal memory instruction.','Écris un rappel puis une consigne de mémoire.','Remind me to call. I must remember to call.','Remind prend la personne aidée.']]},
{id:'dependent-prepositions',name:'Dependent Prepositions and Verb Complements',nameFr:'Prépositions liées aux verbes et compléments',group:1,goal:'Learn complete patterns and preserve the roles of their complements.',gap:'Phrasal verbs were introduced, but dependent complements needed their own course.',sections:[
sec('1 · Learn the whole construction','Apprendre une construction complète','Success depends on preparation. She is interested in science. He is proud of his progress. The preposition is part of a conventional pattern and cannot reliably be translated from French. Write depend on something rather than depend alone in your notebook. Add a full sentence with a meaningful context, then a contrasting incorrect form and its explanation. Some words allow several prepositions with different meanings, so a dictionary example is more useful than a universal one-word rule.','Mémorise le mot avec sa préposition et son complément : depend on, interested in, proud of.'),
sec('2 · A preposition before an action','Préposition suivie d’une action','They succeeded in solving the problem. She insisted on checking the list. After a preposition, an action commonly appears as an -ing form rather than a bare infinitive. I look forward to meeting you contains prepositional to, not the infinitive marker in I want to meet you. The visible word to therefore does not automatically require a base verb. First identify the full expression, then decide what grammatical kind of complement it takes.','Compare want to meet et look forward to meeting. Dans le second cas, to appartient à une expression prépositionnelle.'),
sec('3 · Keep the person in the pattern','Conserver la place de la personne','The rain prevented us from leaving. Prevent someone from doing something requires the affected person or thing before from. Thank someone for helping and accuse someone of cheating use different prepositions and different meanings. An accusation does not establish that the action happened; grammar does not remove uncertainty about facts. In a transformation, preserve who acts, who is affected and whether the claim is certain. Do not merely insert a preposition wherever there is an empty space.','Prevent us from leaving : us est le groupe empêché. Conserve les rôles quand tu reformules la phrase.'),
sec('4 · Recipient, organisation and reason','Destinataire, organisme et raison','She apologised to the teacher for arriving late. To identifies the recipient and for introduces the reason. He applied to the company for a position. The organisation and the desired position have different grammatical roles. Agree with a person, agree on a plan and agree to a proposal are common patterns; context and meaning matter. A sentence can contain several prepositions without redundancy when each introduces a different relationship. Label these relationships before choosing an answer.','Apologise to someone for something ; apply to an organisation for a position. Les deux compléments ne sont pas interchangeables.'),
sec('5 · Adjectives, nouns and direct objects','Adjectifs, noms et compléments directs','Good at organising describes a skill; responsible for the equipment describes responsibility. A reason for a change and an increase in prices are useful noun patterns. Other verbs take a direct object: enter the hall, discuss the problem, reach the station. Explain the rule to me is standard; explain me the rule is not the ordinary standard pattern. Do not assume all verbs meaning communication accept the same structure as tell me the answer.','Explain something to someone, mais tell someone something. Le sens voisin ne garantit pas la même syntaxe.'),
sec('6 · Build and check a pattern notebook','Construire un carnet de modèles','For every new entry, record the headword, the preposition, the type of complement and a contrast. For example: succeed in + noun or -ing; succeed in the task; succeed in completing it. Practise retrieving the entire phrase before looking at the model. In proofreading, check unnecessary prepositions as well as missing ones. If more than one construction is possible, explain which meaning your sentence expresses. A useful correction teaches a reusable pattern rather than just naming the missing word.','Révise les prépositions manquantes et celles qu’on ajoute à tort. Justifie chaque correction avec une phrase modèle complète.')],rows:[
['Success depends ___ preparation.','on','of','at','Le modèle est depend on something. On relie ici la réussite à sa condition.'],
['They succeeded in ___ the problem. (solve)','solving','solve','solved','In est une préposition ; l’action qui suit prend ici la forme -ing : solving.'],
['The rain prevented us ___ leaving.','from','to','of','Prevent someone from doing something est le modèle ; us nomme les personnes empêchées.'],
['She apologised to the teacher ___ arriving late.','for','at','with','For introduit la raison de l’excuse ; to introduit déjà son destinataire.'],
['He applied ___ the company for a position.','to','of','with','Apply to introduit ici l’organisme ; apply for introduit le poste demandé.'],
['Choose the standard sentence for explaining a rule to a listener.','Please explain the rule to me.','Please explain me the rule.','Please explain to the rule me.','Le modèle standard est explain something to someone ; il ne suit pas le double objet de tell.'],
['She is good ___ organising meetings.','at','on','to','Good at + nom ou -ing décrit une compétence ; good to someone aurait un autre sens.'],
['Choose the standard sentence about going inside.','The visitors entered the hall.','The visitors entered at to the hall.','The visitors entered to the hall.','Enter prend directement le lieu dans cette phrase : entered the hall.']],production:['Describe a project using depend on, succeed in + -ing and apologise to someone for something.','Our plan depends on transport. We succeeded in finding a bus. We apologised to the group for arriving late.','Respecte les trois constructions, les rôles des compléments et la forme -ing après in et for.'],objectives:[['State a condition with depend on.','Exprime une condition avec depend on.','The plan depends on the weather.','On introduit la condition.'],['Use three prepositions followed by -ing forms.','Emploie trois prépositions suivies de -ing.','We succeeded in agreeing and insisted on checking before leaving.','Repère chaque préposition et son complément.'],['Describe prevention and identify the affected person.','Exprime un empêchement et la personne concernée.','The delay prevented us from attending.','Conserve personne + from + -ing.'],['Give an apology with a recipient and a reason.','Précise destinataire et raison d’une excuse.','I apologised to her for interrupting.','To nomme la personne ; for la raison.'],['Correct an unnecessary preposition and explain the pattern.','Corrige une préposition inutile.','Discuss about the plan becomes discuss the plan.','Discuss prend directement le sujet discuté.']]},
{id:'sentence-structure',name:'Building Complete Sentences: Clauses and Punctuation',nameFr:'Phrases complètes : propositions et ponctuation',group:0,goal:'Repair fragments, comma splices and unclear parallel structures.',gap:'Connectors existed, but sentence-boundary repair needed explicit practice.',sections:[
sec('1 · Find the subject and finite verb','Sujet et verbe conjugué','The pupils preparing the exhibition is not normally a complete statement: preparing alone does not supply a finite verb. The pupils are preparing the exhibition is complete. A finite verb carries tense or works with an auxiliary. Imperatives such as Read the instructions are complete even though their subject you is understood. Headings and notes can deliberately use fragments; formal essay paragraphs normally need complete sentences. Identify the purpose of the text before declaring every short expression incorrect.','Une forme en -ing seule ne remplace pas un verbe conjugué. Mais un impératif peut être complet sans sujet écrit.'),
sec('2 · Main clauses and subordinate clauses','Proposition principale et subordonnée','Because the rain was heavy introduces a cause but normally leaves a formal sentence unfinished. Add a main clause: Because the rain was heavy, we stayed indoors. Because of the heavy rain uses a noun phrase instead. A short answer beginning with because can be natural in conversation; that does not make the same fragment suitable everywhere in an essay. Check whether the reader receives both the circumstance and the main claim. Do not confuse a long subordinate clause with a complete sentence.','Because + proposition ; because of + groupe nominal. Une subordonnée longue peut toujours avoir besoin d’une principale.'),
sec('3 · Join independent clauses correctly','Relier deux propositions indépendantes','The road was blocked, we waited joins two independent clauses with only a comma. In formal writing, repair this comma splice with a full stop, a semicolon, or a suitable conjunction: The road was blocked, so we waited. A semicolon links closely related complete clauses; it does not supply a missing verb. Choosing so adds a consequence relationship. Choosing but would express contrast instead. A grammatical repair must preserve the intended reasoning, not merely change punctuation.','Une virgule seule ne suffit généralement pas à relier deux principales en rédaction formelle. Choisis aussi le bon lien logique.'),
sec('4 · Avoid duplicate links','Éviter les doubles liens','Although the task was difficult, we finished it is standard. Do not normally add but to introduce the same main clause after although. Likewise, Because the library was closed, we went home does not need so to introduce that same main clause. This is not a ban on both words anywhere in a longer sentence: different clause relationships can require different links. However is an adverbial connector, so The task was difficult; however, we finished it uses different punctuation from a simple coordinating conjunction.','Ne traduis pas mécaniquement bien que… mais ou parce que… donc. Repère quelles propositions chaque mot relie.'),
sec('5 · Parallel structures and clear modifiers','Parallélisme et modificateurs clairs','Our aims are to collect books, organise sessions and support beginners uses parallel verb forms. Mixing supporting into this list disrupts its structure. Walking to school, I saw a notice clearly identifies who was walking. Walking to school, the notice was blue wrongly appears to make the notice the walker. Repair the subject or expand the opening clause: While I was walking to school, I saw a blue notice. Parallelism and modifier placement help the reader follow relationships without guessing.','Dans une liste, garde des formes compatibles. Le sujet après une ouverture en -ing doit correspondre à l’acteur de cette action.'),
sec('6 · Proofread meaning and boundaries','Relire le sens et les limites','Underline every main verb, identify each subject, and mark where each complete clause ends. Then inspect conjunctions, punctuation and parallel lists. Read the corrected sentence aloud, but do not rely only on where you pause: punctuation follows structure as well as rhythm. Finally compare the original and revised meanings. A revision must not turn a possibility into certainty or change who acted. In an exam, a short explanation such as missing auxiliary or two independent clauses is more useful than simply saying the sentence sounds wrong.','Relis séparément les verbes, les liens et la ponctuation. Une correction réussie conserve aussi les acteurs et le degré de certitude.')],rows:[
['The pupils ___ preparing the display now.','are','do','have','Le présent continu demande be + -ing ; are s’accorde avec pupils au pluriel.'],
['___ the rain was heavy, we stayed indoors. (Give the cause.)','Because','Because of','Despite','Because introduit une proposition avec sujet et verbe ; because of et despite demanderaient ici un groupe nominal ou une forme adaptée.'],
['Choose the correctly joined sentence expressing a consequence.','The road was blocked, so we waited.','The road was blocked, we waited.','The road was blocked we waited.','So relie les deux propositions et exprime la conséquence ; une virgule seule ou aucune séparation ne convient pas ici.'],
['Our aims are to collect books, organise sessions and ___ beginners.','support','supporting','supported','Support conserve la série de bases verbales dépendant du même to : collect, organise, support.'],
['Choose a complete standard sentence for a formal essay.','Although the task was difficult, we finished it.','Although the task was difficult.','Although the task was difficult, but we finished it.','La première phrase comporte une subordonnée et une principale sans doubler although par but.'],
['Choose the sentence that clearly identifies the person walking.','Walking to school, I saw a notice.','Walking to school, the notice was blue.','Walking to school, the notice surprised me.','I est le sujet qui marche ; les autres phrases rattachent maladroitement walking au panneau.'],
['Which mark can join two closely related independent clauses without a conjunction?','a semicolon','an apostrophe','no punctuation','Le point-virgule peut relier deux propositions indépendantes liées ; l’apostrophe ne remplit pas cette fonction.'],
['Choose the standard causal sentence.','Because the library was closed, we went home.','Because the library was closed, so we went home.','Because of the library was closed, we went home.','Because introduit la subordonnée et la principale suit sans so ; because of ne prend pas ici une proposition conjuguée.']],production:['Write three sentences about a delayed project. Include a subordinate clause, a consequence and three parallel actions.','Because the bus was late, we changed our plan. We needed more time, so we postponed the meeting. We agreed to check the list, call the members and prepare the room.','Vérifie les principales complètes, le lien de conséquence et les trois formes verbales parallèles.'],objectives:[['Turn an -ing note into a complete sentence.','Transforme une note en -ing en phrase complète.','The pupils preparing becomes The pupils are preparing.','Ajoute un auxiliaire accordé et un contexte clair.'],['Complete a subordinate clause with a main clause.','Ajoute une principale à une subordonnée.','Although it rained, we continued.','La principale apporte l’affirmation centrale.'],['Repair a comma splice in two ways and explain any change of meaning.','Corrige une virgule fautive de deux façons.','It rained; we waited. It rained, so we waited.','So explicite une conséquence ; le point-virgule ne la nomme pas.'],['Write three parallel aims.','Rédige trois objectifs parallèles.','We aim to read, discuss and revise.','Conserve des formes syntaxiques parallèles.'],['Repair a dangling modifier.','Corrige un modificateur mal rattaché.','Walking home, the bag broke becomes While I was walking home, the bag broke.','L’acteur de walking doit être explicite.']]},
{id:'numbers-measures',name:'Numbers, Dates, Prices and Measurements',nameFr:'Nombres, dates, prix et mesures',group:1,goal:'Communicate amounts precisely and interpret numerical information.',gap:'Prices occurred in contexts; number forms and interpretation needed a dedicated lesson.',sections:[
sec('1 · Exact and approximate quantities','Quantités exactes et approximatives','Three hundred pupils gives an exact number: hundred does not take s after three. Hundreds of pupils gives an unspecified large quantity: hundreds takes s and is followed by of. The same distinction applies to thousand and million. When listening, thirteen and thirty or fifteen and fifty can easily be confused. Ask for confirmation rather than guessing a price or time. Forty is the standard spelling, not fourty. Write numbers in context so that precision serves an actual message.','Three hundred, mais hundreds of. Une quantité exacte et une approximation utilisent des constructions différentes.'),
sec('2 · Ordinals and unambiguous dates','Ordinaux et dates claires','First, second and third are irregular ordinal forms. Twenty-first combines the cardinal twenty with first. Dates written only as digits can be ambiguous: 04/05/2026 can represent different months under different conventions. Writing 4 May 2026 makes the intended date clear to an international reader. Capitalise English month and weekday names. When interpreting a source, do not silently guess its date convention; use surrounding evidence or state your assumption. A correctly spelled date can still communicate the wrong day if you reverse month and day.','Écris le mois en lettres pour éviter l’ambiguïté. Les noms anglais des mois et des jours commencent par une majuscule.'),
sec('3 · Decimals, fractions and units','Décimales, fractions et unités','In ordinary English numerical notation, 2.5 uses a decimal point and is read two point five. A comma commonly separates thousands, as in 2,500. A third is one of three equal parts; three quarters means three of four equal parts. Include the unit: 2.5 kilometres is not the same quantity as 2.5 metres. Read both the digits and the surrounding words. If a table follows a different regional convention, inspect its headings and examples before interpreting a separator.','Le point décimal anglais diffère de la virgule souvent utilisée en français. L’unité fait partie de l’information à comprendre.'),
sec('4 · Percentages and percentage points','Pourcentages et points de pourcentage','Twenty percent of fifty is ten: multiply fifty by twenty and divide by one hundred. An increase from twenty percent to thirty percent is ten percentage points. Relative to the original twenty percent, it is a fifty percent increase. These descriptions answer different questions. In a reading passage, also identify the group measured: twenty percent of respondents does not automatically mean twenty percent of every pupil in the country. A careful summary preserves the denominator and the scope of the evidence.','Distingue variation en points et variation relative. Conserve le groupe observé : un échantillon ne représente pas automatiquement toute la population.'),
sec('5 · Prices and measurements','Prix et mesures','Five notebooks at three hundred francs each cost fifteen hundred francs before any additional fee. Including delivery and excluding delivery change the total comparison. Check quantity, unit price and extra charges separately. Kilometres takes a plural ending as a word, but the unit symbol km does not become kms in standard unit notation. Compare offers only under equivalent conditions. A lower advertised unit price may produce a higher final total when a delivery charge is added. Explain your calculation in a full sentence.','Each signifie par article. Vérifie les frais et l’unité avant de comparer deux offres ; km est un symbole invariant.'),
sec('6 · Confirm information in real communication','Vérifier les informations pratiques','When a phone message contains an unclear number, ask Do you mean fifteen or fifty? A written invitation should state a clear date, time, place and any fee. Six in the evening is 6 p.m. or 18:00, whereas 6 a.m. is morning. Avoid unsupported assumptions about ambiguous noon or midnight labels; write the time explicitly when needed. Before submitting a composition or comprehension answer, compare quantities written in words with their digits and check that the conclusion matches the calculation.','Une clarification précise évite une erreur réelle. Dans une invitation, vérifie ensemble date, heure, lieu et coût.')],rows:[
['Choose the standard exact quantity.','three hundred pupils','three hundreds pupils','three hundreds of pupils','Après three, hundred reste sans s et sans of devant pupils ; hundreds of exprimerait une quantité indéfinie.'],
['Write the ordinal for 21.','twenty-first','twenty-oneth','twenty-onefirst','L’ordinal composé est twenty-first : seul le dernier élément devient ordinal.'],
['Read the decimal 2.5 in words.','two point five','two thousand five','twenty-five','Le point est décimal : two point five. Il ne marque pas ici des milliers.'],
['Twenty percent of fifty is ___.','ten','twenty','twenty-five','50 × 20 / 100 = 10. Il faut appliquer le pourcentage au total indiqué.'],
['Which date avoids a month/day convention ambiguity?','4 May 2026','04/05/26','05/04/26','Le mois écrit en lettres rend le jour et le mois explicites ; les deux écritures numériques dépendent de conventions.'],
['Five notebooks cost 300 francs each, with no extra fee. What is the total?','1,500 francs','300 francs','5,300 francs','Le total est quantité × prix unitaire : 5 × 300 = 1 500 francs.'],
['A rate rises from 20% to 30%. The increase in percentage points is ___.','ten','fifty','thirty','30 − 20 = 10 points de pourcentage ; 50% serait la hausse relative au taux initial.'],
['___ of pupils attended. (An unspecified large number.)','Hundreds','Three hundred','Hundred','Hundreds of exprime une grande quantité indéfinie ; un nombre exact demanderait three hundred pupils sans of.']],production:['Write an invitation with a date in words, a 24-hour time and the total price of four items costing 250 francs each.','Meet us on 4 May 2026 at 18:00. Four notebooks at 250 francs each cost 1,000 francs in total.','Vérifie le mois explicite, l’heure sur 24 heures, le produit 4 × 250 et l’unité monétaire.'],objectives:[['Contrast an exact quantity and an unspecified large quantity.','Oppose quantité exacte et grande quantité indéfinie.','Three hundred people came. Hundreds of people came.','Contrôle s et of selon le sens.'],['Rewrite a numeric date unambiguously and state your assumption.','Clarifie une date numérique en indiquant ton hypothèse.','Assuming day/month order, 04/05/2026 is 4 May 2026.','Ne devine pas silencieusement la convention.'],['Write and read a decimal with its unit.','Écris et lis une décimale avec son unité.','2.5 km means two point five kilometres.','Conserve la valeur et l’unité.'],['Calculate a percentage and identify the total group.','Calcule un pourcentage et nomme le groupe total.','Twenty percent of fifty respondents is ten respondents.','La réponse doit conserver le dénominateur et la population.'],['Compare two prices including their extra fees.','Compare deux prix avec leurs frais.','A costs 900 plus 200 delivery; B costs 1,000 including delivery, so B is cheaper.','Compare les totaux et explique la différence.']]}
];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const extensionChapters=extensionSpecs.map(c=>({...c,nameEn:c.name,englishReady:true,sections:c.sections.map(s=>({...s,html:`<p lang="en">${esc(s.english)}</p><details class="language-help"><summary>French help · Aide en français</summary><p lang="fr">${esc(s.help)}</p></details>`})),tasks:[...c.rows.slice(0,4).map(([prompt,answer,bad1,bad2,why],i)=>({prompt:prompt+' Choose from: '+[answer,bad1,bad2].map((_,j)=>[answer,bad1,bad2][(j+i)%3]).join(' / ')+'.',answer,why})),{prompt:c.production[0],answer:c.production[1],why:c.production[2],manual:true}]}));
export const extensionQuestions=extensionSpecs.flatMap(c=>c.rows.map(([prompt,good,bad1,bad2,why],i)=>{const answers=[good,bad1,bad2],offset=i%3;return{id:`v5-${c.id}-${i}`,skill:c.id,level:i<3?1:i<6?2:3,prompt,options:answers.map((_,j)=>answers[(j+offset)%3]),correct:(3-offset)%3,reasons:answers.map((_,j)=>(j+offset)%3===0?why:`« ${answers[(j+offset)%3]} » ne correspond pas au sens ou à la construction demandés. ${why}`)}}));
export const extensionObjectives=Object.fromEntries(extensionSpecs.map(c=>[c.id,c.objectives.map(([en,fr,model,criteria])=>[fr,criteria,model])]));
export const extensionEnglish=Object.fromEntries(extensionSpecs.map(c=>[c.id,c.objectives.map(o=>o[0]).join('|')]));
